from pathlib import Path

import pytest

from specrig.code import read
from specrig.code.calls import path
from specrig.tool.service import Service

FIXTURES = Path(__file__).parent / "fixtures"


def test_a_fastapi_service_serves_its_routers_under_their_prefixes_and_calls_through_its_clients() -> None:
    found = read(Service(FIXTURES / "fastapi"), "gateway")

    assert found.encode() == (
        "# Generated by `specrig surface` from the service's code.\n"
        "specrig: surface/1\n"
        "service: gateway\n"
        "serves:\n"
        "  - GET /api/orders/{order_id}\n"
        "  - GET /files/*\n"
        "  - GET /health\n"
        "  - POST /api/orders/{order_id}/notes\n"
        "  - PUT /api/orders/{order_id}/notes\n"
        "calls:\n"
        "  - GET /customers/{}\n"
        "  - GET /health\n"
        "  - GET external\n"
        "  - POST /customers/{}/notes\n"
        "clients:\n"
        "  gateway.crm.Crm:\n"
        "    - GET /customers/{}\n"
        "    - POST /customers/{}/notes\n"
        "  gateway.sessions:\n"
        "    - GET /health\n"
        "    - GET external\n"
    )


def test_a_setting_without_a_fallback_is_needed_and_one_with_a_fallback_optional() -> None:
    found = read(Service(FIXTURES / "fastapi"), "gateway")

    assert found.encode_checks() == (
        "# Generated by `specrig surface` from the service's code: what its boot is checked against.\n"
        "specrig: checks/1\n"
        "service: gateway\n"
        "settings:\n"
        "  - CRM_TOKEN\n"
        "  - DATABASE_URL\n"
        "  - GATEWAY_CRM_URL\n"
        "optional:\n"
        "  - GATEWAY_CRM_TIMEOUT\n"
        "  - REDIS_URL\n"
    )


def test_a_django_service_serves_its_urlconf_by_the_methods_its_views_answer() -> None:
    found = read(Service(FIXTURES / "django"), "stock")

    assert sorted(found.serves) == [
        "* /legacy/{sku}",
        "DELETE /api/files/*",
        "GET /api/files/*",
        "GET /api/items/{item}",
        "GET /api/reservations",
        "POST /api/reservations",
    ]
    assert found.clients == {"stock.warehouse.Warehouse": {"POST /reservations/{}"}}


def test_a_django_service_reads_its_settings_through_django_environ_and_os() -> None:
    found = read(Service(FIXTURES / "django"), "stock")

    assert sorted(found.settings) == ["DATABASE_URL", "SECRET_KEY", "WAREHOUSE_URL"]
    assert sorted(found.optional) == ["DEBUG", "RESERVE_LIMIT"]


@pytest.mark.parametrize(
    ("template", "named"),
    [
        ("/invoices/{}", "/invoices/{}"),
        ("{}/invoices", "/invoices"),
        ("https://billing.test/invoices?status=paid", "/invoices"),
        ("{}", "external"),
        ("/{}/invoices", "/{}/invoices"),
        ("/orders/x{}", "/orders/{}"),
    ],
)
def test_a_request_is_named_by_its_path_with_what_varies_as_braces(template: str, named: str) -> None:
    assert path(template) == named


def test_a_route_that_is_not_a_constant_is_refused(tmp_path: Path) -> None:
    (tmp_path / "pyproject.toml").write_text('[project]\nname = "x"\ndependencies = ["fastapi"]\n')
    (tmp_path / "main.py").write_text(
        "import os\nfrom fastapi import FastAPI\n\napp = FastAPI()\n\n\n@app.get(os.environ['ROUTE'])\ndef any() -> None:\n    pass\n"
    )

    with pytest.raises(ValueError, match="main.py:7: serves a route that is not a constant"):
        read(Service(tmp_path), "x")
